"use client";

import MathRenderer from "@/components/MathRenderer";
import { CHAPTERS_REGISTRY } from "@/lib/chapters";
import { evaluateVentureProject } from "@/lib/jury";
import type {
  ProjectEvaluationReport,
  ProjectVentureSubmission,
  StudentSubmissionReport,
  Worksheet,
} from "@/lib/types";
import { useEffect, useMemo, useState } from "react";

interface WorksheetPreviewProps {
  worksheet: Worksheet | null;
  studentId?: string;
  hideAnswerKeyUntilSubmit: boolean;
  hasSubmittedCurrentWorksheet: boolean;
  activeToast?: {
    message: string;
    type: "SUCCESS" | "INFO";
  } | null;
  onCloseToast?: () => void;
  worksheetId?: string | null;
  filters?: {
    difficulty?: string;
    subject?: string;
    grade?: string;
  };
  onSubmitEvaluation?: (report: StudentSubmissionReport) => void;
}

function renderMathText(text: string) {
  const needsMathFormatting = /[=]|\^|_|\*|\/|\+|\-/ .test(text);

  if (!needsMathFormatting) {
    return text;
  }

  return <MathRenderer formula={text} />;
}

export default function WorksheetPreview({
  worksheet,
  studentId,
  hideAnswerKeyUntilSubmit,
  hasSubmittedCurrentWorksheet,
  activeToast,
  onCloseToast,
  worksheetId,
  filters,
  onSubmitEvaluation,
}: WorksheetPreviewProps) {
  const [localAnswers, setLocalAnswers] = useState<Record<string, string>>({});
  const [hasSubmittedLocally, setHasSubmittedLocally] = useState<boolean>(false);
  const [ventureName, setVentureName] = useState("");
  const [executiveSummaryText, setExecutiveSummaryText] = useState("");
  const [technicalArchitectureSpecs, setTechnicalArchitectureSpecs] = useState("");
  const [ventureReport, setVentureReport] = useState<ProjectEvaluationReport | null>(null);

  const uniquePrinciples = useMemo(() => {
    if (!worksheet) return [];

    return Array.from(
      new Map(
        worksheet.questions
          .filter((question) => question.principle)
          .map((question) => [question.principle!.id, question.principle!]),
      ).values(),
    );
  }, [worksheet]);

  useEffect(() => {
    // A newly generated worksheet must not inherit the previous worksheet's unlocked answers.
    // eslint-disable-next-line react-hooks/set-state-in-effect
    setHasSubmittedLocally(false);
  }, [worksheet?.id]);

  if (!worksheet || worksheet.questions.length === 0) {
    return (
      <div className="space-y-4">
        {activeToast && (
          <div
            role="status"
            className={`toast-enter flex items-center justify-between rounded-xl border p-4 text-xs font-medium ${
              activeToast.type === "SUCCESS"
                ? "border-emerald-200 bg-emerald-50 text-emerald-800"
                : "border-zinc-200 bg-zinc-50 text-zinc-800"
            }`}
          >
            <span>{activeToast.message}</span>
            <button
              type="button"
              onClick={onCloseToast}
              className="ml-2 font-mono font-bold text-zinc-400 hover:text-zinc-900"
              aria-label="Dismiss notification"
            >
              ✕
            </button>
          </div>
        )}
        <div className="no-print rounded-xl border border-dashed border-zinc-300 bg-zinc-50 p-12 text-center text-sm font-medium text-zinc-400">
          Choose a chapter and parameters on the filter panel to assemble a worksheet preview.
        </div>
      </div>
    );
  }

  const chosenDifficulty = filters?.difficulty ?? worksheet.filters.difficulty ?? "Mixed";
  const chosenSubject = filters?.subject ?? worksheet.filters.subject ?? "Physics";
  const chosenGrade = filters?.grade ?? worksheet.filters.grade ?? "11";
  const totalMarks = worksheet.questions.reduce((sum, question) => sum + question.marks, 0);
  const activeTrack = worksheet.filters.trackTypes?.[0];
  const isFutureTechLab = activeTrack === "FUTURE_TECH_LAB";

  function handleOptionSelect(questionId: string, option: string) {
    setLocalAnswers((current) => ({
      ...current,
      [questionId]: option,
    }));
  }

  function handleTextInput(questionId: string, value: string) {
    setLocalAnswers((current) => ({
      ...current,
      [questionId]: value,
    }));
  }

  function submitVentureCanvas() {
    if (!worksheet || !ventureName.trim() || !executiveSummaryText.trim() || !technicalArchitectureSpecs.trim()) {
      return;
    }

    const submission: ProjectVentureSubmission = {
      projectId: worksheet.id,
      studentId: studentId?.trim() || "unknown",
      subtopic: worksheet.questions[0]?.subtopic ?? worksheet.questions[0]?.topic ?? "Future Technology Lab",
      ventureName: ventureName.trim(),
      executiveSummaryText: executiveSummaryText.trim(),
      technicalArchitectureSpecs: technicalArchitectureSpecs.trim(),
      submittedAt: new Date().toISOString(),
    };

    setVentureReport(evaluateVentureProject(submission));
    setHasSubmittedLocally(true);
  }

  function evaluateStudentSubmission(answers: Record<string, string> = localAnswers) {
    if (!worksheet) return;

    const savedAnswers = { ...answers };

    const responses = worksheet.questions.map((question) => {
      const rawAnswer = savedAnswers[question.id] ?? "";
      const normalizedStudentAnswer = rawAnswer.trim().toLowerCase().replace(/\s*,\s*/g, ",");
      const correctAnswerText = question.correctAnswer ?? question.answer ?? "";
      const normalizedCorrectAnswer = correctAnswerText.trim().toLowerCase().replace(/\s*,\s*/g, ",");
      const isCorrect =
        normalizedStudentAnswer.length > 0 &&
        normalizedStudentAnswer === normalizedCorrectAnswer;

      return {
        questionId: question.id,
        questionText: question.text ?? question.stem ?? "Untitled question",
        studentAnswer: rawAnswer.trim() || "Not attempted",
        correctAnswer: correctAnswerText,
        isCorrect,
        marksAwarded: isCorrect ? question.marks : 0,
      };
    });

    const scoreObtained = responses.reduce((sum, response) => sum + response.marksAwarded, 0);
    const maxPossibleMarks = worksheet.questions.reduce((sum, question) => sum + question.marks, 0);

    const report: StudentSubmissionReport = {
      submissionId: `submission-${Date.now()}`,
      studentId: studentId?.trim() || "unknown",
      portalType:
        worksheet.filters.preparationLevel === "FOUNDATION"
          ? "FOUNDATION"
          : "JEE_MAIN_ADVANCED",
      subject: worksheet.filters.subject,
      worksheetId: worksheet.id,
      chapterId: worksheet.filters.chapter,
      chapterTitle:
        CHAPTERS_REGISTRY.find((chapter) => chapter.id === worksheet.filters.chapter)?.title ??
        worksheet.filters.chapter,
      trackType:
        worksheet.filters.trackTypes?.[0] ??
        (worksheet.filters.preparationLevel === "FOUNDATION"
          ? "CONCEPTUAL_QUIZ"
          : "JEE_MAIN_DRILL"),
      generatedAt: worksheet.generatedAt,
      submittedAt: new Date().toISOString(),
      totalQuestions: worksheet.questions.length,
      scoreObtained,
      maxPossibleMarks,
      scoreMarks: scoreObtained,
      totalMarks: maxPossibleMarks,
      accuracyPercentage:
        maxPossibleMarks > 0 ? Math.round((scoreObtained / maxPossibleMarks) * 100) : 0,
      responses,
    };

    setHasSubmittedLocally(true);
    onSubmitEvaluation?.(report);
  }

  return (
    <article className="space-y-6 rounded-2xl border border-zinc-200 bg-white p-5 text-left shadow-[0_18px_45px_-30px_rgba(15,23,42,0.45)] sm:p-8 print:border-0 print:p-0 print:shadow-none">
      {activeToast && (
        <div
          role="status"
          className={`toast-enter flex items-center justify-between rounded-xl border p-4 text-xs font-medium transition-all ${
            activeToast.type === "SUCCESS"
              ? "border-emerald-200 bg-emerald-50 text-emerald-800"
              : "border-zinc-200 bg-zinc-50 text-zinc-800"
          }`}
        >
          <span>{activeToast.message}</span>
          <button
            type="button"
            onClick={onCloseToast}
            className="ml-2 font-mono font-bold text-zinc-400 hover:text-zinc-900"
            aria-label="Dismiss notification"
          >
            ✕
          </button>
        </div>
      )}

      {uniquePrinciples.length > 0 && (
        <section className="no-print rounded-xl border border-zinc-200 bg-zinc-50 p-5">
          <h2 className="mb-1.5 text-xs font-bold uppercase tracking-widest text-zinc-800">
            Dynamic Formula and Phenomenon Reference Index
          </h2>
          <p className="mb-3 text-xs leading-relaxed text-zinc-500">
            Core governing physics parameters represented in this worksheet.
          </p>
          <div className="grid grid-cols-1 gap-2.5 text-xs">
            {uniquePrinciples.map((principle) => (
              <div key={principle.id} className="rounded-lg border border-zinc-200 bg-white p-3 shadow-sm">
                <div className="text-sm font-semibold text-zinc-800">{principle.name}</div>
                <div className="mt-0.5 leading-normal text-zinc-500">
                  Physical phenomenon: {principle.phenomenon}
                </div>
                <div className="mt-2 inline-block rounded border border-zinc-200 bg-zinc-50 px-2 py-1 text-zinc-900">
                  Governing formula: <MathRenderer formula={principle.governingFormula} />
                </div>
              </div>
            ))}
          </div>
        </section>
      )}

      <header className="flex flex-col gap-4 border-b border-zinc-200 pb-5 sm:flex-row sm:items-start sm:justify-between">
        <div>
          <span className="font-mono text-xs font-medium uppercase tracking-widest text-zinc-400">
            Class {chosenGrade} · {chosenSubject} · NCERT Preparation
          </span>
          <h1 className="mt-0.5 text-2xl font-bold text-zinc-900">
            {worksheet.title || "Evaluation Practice Worksheet"}
          </h1>
          {worksheetId && (
            <p className="mt-1 font-mono text-xs text-zinc-400">Sheet Signature ID: {worksheetId}</p>
          )}
        </div>
        <div className="space-y-0.5 rounded-xl border border-zinc-200 bg-zinc-50 p-3 text-left text-xs font-medium text-zinc-600 sm:text-right">
          <div><strong>Total items:</strong> {worksheet.questions.length} questions</div>
          <div><strong>Difficulty matrix:</strong> {chosenDifficulty}</div>
          <div><strong>Maximum marks:</strong> {totalMarks} marks</div>
        </div>
      </header>

      {isFutureTechLab ? (
        <section className="no-print rounded-2xl border border-sky-200 bg-sky-50/60 p-5 shadow-sm sm:p-6">
          <div className="mb-5 flex flex-wrap items-start justify-between gap-3">
            <div>
              <p className="text-xs font-bold uppercase tracking-[0.2em] text-sky-700">Future Technology Lab</p>
              <h2 className="mt-1 text-xl font-bold text-zinc-900">Project-based venture evaluation</h2>
              <p className="mt-1 max-w-2xl text-sm leading-relaxed text-zinc-600">
                Present the commercial idea, then ground it in the physical laws and formulas that make the prototype work.
              </p>
            </div>
            <span className="rounded-full border border-sky-200 bg-white px-3 py-1 font-mono text-[10px] font-bold uppercase tracking-wide text-sky-700">
              AI venture jury
            </span>
          </div>

          <div className="grid gap-4">
            <label className="text-sm font-semibold text-zinc-800">
              Venture / Prototype Name
              <input
                type="text"
                value={ventureName}
                onChange={(event) => setVentureName(event.target.value)}
                disabled={hasSubmittedCurrentWorksheet || hasSubmittedLocally}
                placeholder={hasSubmittedCurrentWorksheet || hasSubmittedLocally ? "Locked after submission" : "e.g., Solid-State Quantum Cell Grid"}
                className={`mt-1.5 h-11 w-full rounded-lg border px-3 text-sm font-normal shadow-sm placeholder:text-zinc-400 focus:border-sky-400 focus:outline-none focus:ring-2 focus:ring-sky-100 ${
                  hasSubmittedCurrentWorksheet || hasSubmittedLocally
                    ? "cursor-not-allowed border-zinc-200 bg-zinc-100 text-zinc-400"
                    : "border-zinc-200 bg-white text-zinc-900"
                }`}
              />
            </label>
            <label className="text-sm font-semibold text-zinc-800">
              Executive Commercial Summary
              <textarea
                value={executiveSummaryText}
                onChange={(event) => setExecutiveSummaryText(event.target.value)}
                disabled={hasSubmittedCurrentWorksheet || hasSubmittedLocally}
                placeholder="What problem does this venture solve, and who benefits?"
                rows={4}
                className={`mt-1.5 w-full resize-y rounded-lg border px-3 py-2.5 text-sm font-normal leading-relaxed shadow-sm placeholder:text-zinc-400 focus:border-sky-400 focus:outline-none focus:ring-2 focus:ring-sky-100 ${
                  hasSubmittedCurrentWorksheet || hasSubmittedLocally
                    ? "cursor-not-allowed border-zinc-200 bg-zinc-100 text-zinc-400"
                    : "border-zinc-200 bg-white text-zinc-900"
                }`}
              />
            </label>
            <label className="text-sm font-semibold text-zinc-800">
              Technical Architecture Specifications
              <span className="ml-1 font-normal text-zinc-500">(Detail the governing physical formulas utilized)</span>
              <textarea
                value={technicalArchitectureSpecs}
                onChange={(event) => setTechnicalArchitectureSpecs(event.target.value)}
                disabled={hasSubmittedCurrentWorksheet || hasSubmittedLocally}
                placeholder="Describe the materials, system architecture, governing equations, and measurable constraints."
                rows={7}
                className={`mt-1.5 w-full resize-y rounded-lg border px-3 py-2.5 text-sm font-normal leading-relaxed shadow-sm placeholder:text-zinc-400 focus:border-sky-400 focus:outline-none focus:ring-2 focus:ring-sky-100 ${
                  hasSubmittedCurrentWorksheet || hasSubmittedLocally
                    ? "cursor-not-allowed border-zinc-200 bg-zinc-100 text-zinc-400"
                    : "border-zinc-200 bg-white text-zinc-900"
                }`}
              />
            </label>
          </div>

          <button
            type="button"
            onClick={submitVentureCanvas}
            disabled={hasSubmittedCurrentWorksheet || hasSubmittedLocally || !ventureName.trim() || !executiveSummaryText.trim() || !technicalArchitectureSpecs.trim()}
            className="mt-5 rounded-xl bg-blue-600 px-5 py-3 text-sm font-bold text-white shadow-sm transition hover:bg-blue-500 disabled:cursor-not-allowed disabled:opacity-50"
          >
            Submit Project Canvas to AI Venture Jury
          </button>
        </section>
      ) : (
      <div className="space-y-6 pt-2">
        {worksheet.questions.map((question, index) => (
          <div key={question.id || index} className="break-inside-avoid space-y-3 border-b border-zinc-100 pb-5 last:border-0 last:pb-0">
            <div className="flex items-start justify-between gap-3">
              <span className="text-sm font-semibold text-zinc-900">
                Q{index + 1}. {(question.subtopic || question.topic) && (
                  <span className="ml-2 rounded-md bg-zinc-100 px-2 py-0.5 font-mono text-[11px] font-bold uppercase tracking-wide text-zinc-700">
                    {question.subtopic ?? question.topic}
                  </span>
                )}
                {question.jeeMetrics?.historicalAppearancePercentage != null && (
                  <span className="ml-2 rounded-md bg-amber-100 px-2 py-0.5 font-mono text-[11px] font-bold text-amber-800">
                    🎯 JEE Frequency Rank: {question.jeeMetrics.historicalAppearancePercentage}%
                  </span>
                )}
              </span>
              <span className="whitespace-nowrap font-mono text-xs font-medium text-zinc-400">
                [{question.marks} marks]
              </span>
            </div>
            <p className="whitespace-pre-wrap pl-1 text-sm leading-relaxed text-zinc-800">
              {renderMathText(question.text ?? question.stem ?? "")}
            </p>
            {question.type === "MCQ" && question.options && question.options.length > 0 && (
              <div className="grid grid-cols-1 gap-2.5 pt-1.5 text-sm text-zinc-700 md:grid-cols-2">
                {question.options.map((option, optionIndex) => {
                  const isSelected = localAnswers[question.id] === option;

                  return (
                    <button
                      key={option}
                      type="button"
                      disabled={hasSubmittedCurrentWorksheet || hasSubmittedLocally}
                      onClick={() => handleOptionSelect(question.id, option)}
                      className={`flex items-center rounded-lg border p-2.5 text-left transition ${
                        isSelected
                          ? "border-blue-500 bg-blue-50/50 text-blue-900 shadow-sm"
                          : "border-zinc-200 bg-zinc-50/50 text-zinc-800 hover:border-zinc-300 hover:bg-zinc-50"
                      } disabled:cursor-not-allowed disabled:opacity-60`}
                    >
                          <span className="mr-2 font-mono text-xs font-bold text-zinc-400">
                        {String.fromCharCode(65 + optionIndex)}.
                      </span>
                      <span className="font-medium">{renderMathText(option ?? "")}</span>
                    </button>
                  );
                })}
              </div>
            )}
            {(question.type === "NAT" || question.type === "FITB") && (
              <div className="no-print pt-2">
                <span className="font-mono text-[11px] font-medium uppercase tracking-wide text-zinc-400">
                  {question.type === "NAT" ? "🔢 Numerical Input Field Answer Value:" : "Fill in the blank response"}
                </span>
                <input
                  type="text"
                  value={localAnswers[question.id] ?? ""}
                  onChange={(event) => handleTextInput(question.id, event.target.value ?? "")}
                  disabled={hasSubmittedCurrentWorksheet || hasSubmittedLocally}
                  placeholder={hasSubmittedCurrentWorksheet || hasSubmittedLocally ? "Locked after submission" : "Type numerical value answer..."}
                  className={`mt-2 h-10 w-full max-w-[260px] rounded-lg border px-3 text-sm placeholder:text-zinc-400 focus:border-blue-400 focus:outline-none focus:ring-2 focus:ring-blue-100 ${
                    hasSubmittedCurrentWorksheet || hasSubmittedLocally
                      ? "cursor-not-allowed select-none border-zinc-200 bg-zinc-100 font-bold text-zinc-400"
                      : "border-zinc-200 bg-zinc-50 text-zinc-900"
                  }`}
                />
              </div>
            )}
          </div>
        ))}
      </div>
      )}

      {isFutureTechLab && ventureReport && (
        <section className="rounded-2xl border border-zinc-200 bg-slate-50 p-5 shadow-sm sm:p-6">
          <div className="mb-5 flex items-center justify-between gap-3 border-b border-slate-200 pb-4">
            <div>
              <p className="text-xs font-bold uppercase tracking-[0.2em] text-slate-500">Jury assessment</p>
              <h2 className="mt-1 text-xl font-bold text-slate-900">Venture evaluation scorecard</h2>
            </div>
            <span className="rounded-full bg-slate-900 px-3 py-1.5 text-[10px] font-bold uppercase tracking-wide text-white">
              {ventureReport.overallVerdict.replaceAll("_", " ")}
            </span>
          </div>
          <div className="grid gap-3 sm:grid-cols-3">
            {[
              ["Physics grounding", ventureReport.physicsGroundingScore],
              ["Feasibility", ventureReport.feasibilityScore],
              ["Market potential", ventureReport.marketDisruptionPotential],
            ].map(([label, score]) => (
              <div key={label} className="rounded-xl border border-slate-200 bg-white p-4">
                <p className="text-xs font-semibold text-slate-500">{label}</p>
                <p className="mt-1 font-mono text-2xl font-bold text-slate-900">{score}%</p>
              </div>
            ))}
          </div>
          <div className="mt-4 grid gap-4 md:grid-cols-2">
            <div className="rounded-xl border border-rose-200 bg-rose-50 p-4">
              <h3 className="text-sm font-bold text-rose-900">Critical technical flaws</h3>
              <ul className="mt-2 list-disc space-y-1 pl-4 text-sm leading-relaxed text-rose-800">
                {ventureReport.criticalTechnicalFlaws.map((flaw) => <li key={flaw}>{flaw}</li>)}
              </ul>
            </div>
            <div className="rounded-xl border border-emerald-200 bg-emerald-50 p-4">
              <h3 className="text-sm font-bold text-emerald-900">Suggested next-gen milestones</h3>
              <ul className="mt-2 list-disc space-y-1 pl-4 text-sm leading-relaxed text-emerald-800">
                {ventureReport.suggestedAdvancementsMilestones.map((milestone) => <li key={milestone}>{milestone}</li>)}
              </ul>
            </div>
          </div>
        </section>
      )}

      {!isFutureTechLab && <div className="no-print flex justify-end gap-3 border-t border-zinc-200 pt-5">
        <button
          type="button"
          onClick={() => window.print()}
          className="rounded-xl border border-zinc-300 bg-white px-5 py-2.5 text-xs font-semibold tracking-wide text-zinc-800 shadow-sm transition hover:bg-zinc-50"
        >
          Print / Save PDF
        </button>
        <button
          type="button"
          onClick={() => evaluateStudentSubmission(localAnswers)}
          disabled={hasSubmittedCurrentWorksheet || hasSubmittedLocally}
          className="rounded-xl bg-blue-600 px-5 py-2.5 text-xs font-semibold tracking-wide text-white shadow-sm transition hover:bg-blue-500 disabled:cursor-not-allowed disabled:opacity-60"
        >
          Submit Answers for Evaluation
        </button>
      </div>}

      {!isFutureTechLab && worksheet.filters.includeAnswerKey && (
        (!hideAnswerKeyUntilSubmit || hasSubmittedCurrentWorksheet || hasSubmittedLocally) ? (
          <div className="mt-6 rounded-xl border border-zinc-200 bg-zinc-50 p-6 text-left">
            <h3 className="mb-3 text-sm font-extrabold uppercase tracking-wider text-zinc-900">
              🔑 Official Answer Key &amp; Technical Explanations
            </h3>
            <ol className="answer-key space-y-3 border-t border-zinc-200 pt-4 text-sm">
              {worksheet.questions.map((q, i) => (
                <li key={q.id}>
                  <span className="font-medium">
                    {i + 1}. <MathRenderer formula={q.correctAnswer ?? q.answer ?? ""} />
                  </span>
                  <p className="text-zinc-600">{q.solution}</p>
                </li>
              ))}
            </ol>
          </div>
        ) : (
          <div className="no-print mt-6 rounded-xl border border-dashed border-amber-300 bg-amber-50/50 p-4 text-center text-xs font-semibold text-amber-800">
            🔒 Solutions Locked. Input your responses and click the blue &quot;Submit Answers for Evaluation&quot; button above to unlock the answer keys.
          </div>
        )
      )}
    </article>
  );
}
