import type { ProjectEvaluationReport, ProjectVentureSubmission } from "./types";

export function evaluateVentureProject(
  submission: ProjectVentureSubmission,
): ProjectEvaluationReport {
  // Calibrate technical architecture depth into a physics score.
  const textLengthCheck = submission.technicalArchitectureSpecs.length;
  let physicsScore = Math.min(40 + textLengthCheck / 10, 98);
  const flaws: string[] = [];
  const milestones: string[] = [];

  if (submission.technicalArchitectureSpecs.toLowerCase().includes("graphene")) {
    physicsScore += 5;
    milestones.push(
      "Integrate double-layer electrostatics equations into manufacturing blueprints.",
    );
  } else {
    flaws.push(
      "Architecture lacks localized physical backing parameters. Ground the technical specifications in core thermodynamics or quantum laws.",
    );
  }

  return {
    evaluationId: `eval_${Math.random().toString(36).slice(2, 11)}`,
    projectId: submission.projectId,
    feasibilityScore: Math.round(physicsScore * 0.9),
    physicsGroundingScore: Math.round(Math.min(physicsScore, 100)),
    marketDisruptionPotential: Math.round(50 + Math.random() * 45),
    criticalTechnicalFlaws:
      flaws.length > 0
        ? flaws
        : ["None identified. Technical physics foundation is highly viable."],
    suggestedAdvancementsMilestones:
      milestones.length > 0
        ? milestones
        : ["Benchmark structural load capacities against industrial safety logs."],
    overallVerdict:
      physicsScore >= 75 ? "VIABLE_SEED_STAGE" : "REVISION_REQUIRED",
  };
}
